steps.codeExample:
int[] senhas = {10, -1, 20, 999, 30};
for (int s : senhas) {
  if (s < 0) continue; // pula cancelado
  if (s == 999) break; // fecha o caixa
  System.out.println("Preparando #" + s);
}

